#include <algorithm>
#include <cstdint>
#include <map>
#include <string>
#include <vector>

struct TagUsage { std::string tag; int allocations; std::uint64_t bytes; };

class PoolTracker
{
public:
    int allocate(const std::string& tag, std::uint64_t bytes)
    {
        const int id{ m_next++ };
        m_live[id] = { tag, bytes };
        return id;
    }

    std::string free(int id, const std::string& tag)
    {
        const auto it{ m_live.find(id) };
        if (it == m_live.end()) return "double free or bad id";
        if (it->second.tag != tag) return "tag mismatch";
        m_live.erase(it);
        return "";
    }

    std::vector<TagUsage> usage() const
    {
        std::map<std::string, TagUsage> byTag;
        for (const auto& [id, a] : m_live)
        {
            TagUsage& u{ byTag.try_emplace(a.tag, TagUsage{ a.tag, 0, 0 }).first->second };
            ++u.allocations;
            u.bytes += a.bytes;
        }
        std::vector<TagUsage> out;
        for (auto& [tag, u] : byTag) out.push_back(u);
        std::stable_sort(out.begin(), out.end(), [](const TagUsage& a, const TagUsage& b) { return a.bytes > b.bytes; });
        return out;
    }

private:
    struct Allocation { std::string tag; std::uint64_t bytes; };
    std::map<int, Allocation> m_live;
    int m_next{ 1 };
};

std::string tagText(std::uint32_t tag)
{
    std::string s;
    for (int i{ 0 }; i < 4; ++i) s += static_cast<char>((tag >> (8 * i)) & 0xFF);   // lowest byte first
    return s;
}

unitTests:
TEST("usage by tag")
{
    PoolTracker p;
    p.allocate("Echo", 100); p.allocate("Echo", 50); p.allocate("Vid ", 4096); p.allocate("Abcd", 150);
    const auto u{ p.usage() };
    CHECK_EQ(u.size(), std::size_t{ 3 });
    CHECK_EQ(u[0].tag, std::string("Vid "));
    CHECK_EQ(u[1].tag, std::string("Abcd"));      // 150 bytes, tie with Echo broken alphabetically
    CHECK_EQ(u[2].tag, std::string("Echo"));
    CHECK_EQ(u[2].allocations, 2);
    CHECK_EQ(u[2].bytes, 150ull);
}
TEST("freeing removes usage") { PoolTracker p; const int a{ p.allocate("Echo", 10) }; CHECK_EQ(p.free(a, "Echo"), std::string("")); CHECK(p.usage().empty()); }
TEST("double free") { PoolTracker p; const int a{ p.allocate("Echo", 10) }; p.free(a, "Echo"); CHECK_EQ(p.free(a, "Echo"), std::string("double free or bad id")); CHECK_EQ(p.free(99, "Echo"), std::string("double free or bad id")); }
TEST("tag mismatch leaves it allocated") { PoolTracker p; const int a{ p.allocate("Echo", 10) }; CHECK_EQ(p.free(a, "Oops"), std::string("tag mismatch")); CHECK_EQ(p.usage().size(), std::size_t{ 1 }); }
TEST("tag text is little-endian") { CHECK_EQ(tagText(0x6F686345u), std::string("Echo")); }

